import yaml, json
d = yaml.safe_load(open('requirements.yaml'))
def find(n, ids, out):
    if n.get('id') in ids: out.append(n)
    for c in n.get('children', []) or []:
        find(c, ids, out)
out=[]
find(d, {'REQ-2-1-1','REQ-2-1-2','REQ-2-1-3','REQ-2-1-4','REQ-2-2-1','REQ-2-2-2'}, out)
for n in out:
    print('='*100)
    print(json.dumps(n, ensure_ascii=False, indent=1))
EOF

